WITH account_summary AS (SELECT account_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values, SUM(amount) AS total_amount FROM transactions WHERE txn_type NOT IN ('FEE', 'DEBIT', 'CREDIT') GROUP BY account_id) SELECT a.id, a.status, as.merchant_values, as.total_amount FROM accounts a INNER JOIN account_summary as ON a.id = as.account_id WHERE as.total_amount >= 15000
